<template>
  <RecyclingShell title="回收运营" :dark="isDark">
    <view v-if="error" class="recycle-error">{{ error }}<button class="recycle-secondary" :disabled="loading" @click="load">重新加载</button></view>
    <view class="recycle-tabs"><button v-for="item in tabs" :key="item.key" class="recycle-pill" :class="{ selected: tab === item.key }" @click="changeTab(item.key)">{{ item.label }}</button><button class="recycle-pill" :disabled="loading" @click="load">刷新</button></view>
    <view v-if="loading && !ready" class="recycle-empty">加载中…</view>
    <template v-if="ready">
      <template v-if="tab === 'applications'">
        <view class="recycle-card"><text class="recycle-heading">申请审核</text><text class="recycle-muted">通过前请核验业务联系方式、服务范围与品类能力。批准后由回收员开启接单并发布排班。</text></view>
        <view v-for="item in overview.applications" :key="item.id" class="recycle-card"><view class="recycle-row"><text class="recycle-heading">{{ item.serviceName }}</text><text class="recycle-status">{{ collectorStatusText(item.status) }}</text></view><text class="recycle-copy">电话：{{ item.phone }}</text><text class="recycle-copy">区域：{{ names(item.areaIds, overview.areas) }}</text><text class="recycle-copy">品类：{{ names(item.typeIds, catalog.types) }}</text><text class="recycle-copy">{{ item.notes || '未填写服务说明' }}</text><text v-if="item.reason" class="recycle-copy">审核说明：{{ item.reason }}</text>
          <button class="recycle-secondary" @click="rangePreviews['app:' + item.id] = !rangePreviews['app:' + item.id]">{{ rangePreviews['app:' + item.id] ? '收起地图' : '核验申请地图范围' }}</button>
          <RecyclingServiceMap v-if="rangePreviews['app:' + item.id]" :areas="applicationAreas(item)" readonly />
          <template v-if="item.status === 'pending'"><textarea v-model="reasons['application:' + item.id]" maxlength="255" placeholder="核验说明 / 驳回原因（驳回必填）" :disabled="busy" /><view class="recycle-row"><button class="recycle-primary recycle-grow" :disabled="busy" @click="review(item, 'approved')">核验通过</button><button class="recycle-danger recycle-grow" :disabled="busy" @click="review(item, 'rejected')">驳回申请</button></view></template>
        </view><view v-if="!overview.applications.length" class="recycle-empty">暂无申请</view>
      </template>
      <template v-if="tab === 'collectors'">
        <view v-for="item in overview.profiles" :key="item.id" class="recycle-card"><view class="recycle-row"><text class="recycle-heading">{{ item.serviceName }}</text><text class="recycle-status">{{ collectorStatusText(item.status) }}</text></view><text class="recycle-copy">账号 {{ item.userId }} · {{ item.phone }}</text><text class="recycle-copy">区域：{{ names(item.areaIds, overview.areas) }}</text><text class="recycle-copy">{{ item.acceptingOrders ? '已开启接单' : '未开启接单' }}</text><text v-if="item.reviewReason" class="recycle-muted">平台说明：{{ item.reviewReason }}</text>
          <template v-if="['approved', 'suspended'].includes(item.status)"><textarea v-model="reasons['profile:' + item.id]" maxlength="255" placeholder="停用 / 恢复原因（必填）" :disabled="busy" /><button :class="item.status === 'approved' ? 'recycle-danger' : 'recycle-primary'" :disabled="busy" @click="profileStatus(item)">{{ item.status === 'approved' ? '停用接单资格' : '恢复接单资格' }}</button><text class="recycle-muted recycle-copy">仍有任务时，请先转派或协商取消，再停用。</text></template>
        </view><view v-if="!overview.profiles.length" class="recycle-empty">暂无回收员</view>
      </template>
      <template v-if="tab === 'orders'">
        <view class="recycle-card"><text class="recycle-heading">预约调度</text><text class="recycle-muted">历史未归区订单需要先核对服务区域；过期未履约订单请与用户联系后取消。转派不会把原私聊记录交给新人员。</text></view>
        <view v-for="item in overview.orders" :key="item.id" class="recycle-card"><view class="recycle-row"><text>{{ item.orderNo }}</text><text class="recycle-status">{{ statusText(item.status) }}</text></view><text class="recycle-copy">{{ item.appointmentDate }} {{ item.appointmentTimeSlot }}</text><text class="recycle-copy">{{ item.serviceAreaName || names([item.serviceAreaId], overview.areas) || '历史订单：区域待核对' }}</text><text class="recycle-copy">{{ item.address }}</text><text class="recycle-copy">{{ item.collectorName ? `接单人：${item.collectorName}` : '尚未指派人员' }}</text>
          <template v-if="['pending', 'confirmed', 'picking'].includes(item.status)">
            <text class="recycle-label">调度说明（必填）</text><textarea v-model="reasons['order:' + item.id]" maxlength="255" placeholder="联系用户情况、取消或人员调整原因" :disabled="busy" />
            <template v-if="!item.serviceAreaId && item.status !== 'picking'"><picker :range="overview.areas" range-key="name" :value="areaSelections[item.id] || 0" @change="areaSelections[item.id] = Number($event.detail.value)"><view class="recycle-select">{{ overview.areas[areaSelections[item.id] || 0]?.name || '暂无已申请服务地区' }}</view></picker><button class="recycle-secondary" :disabled="busy || !overview.areas.length" @click="dispatch(item, 'map')">核对区域并退回待接单</button></template>
            <template v-else-if="item.status !== 'picking'"><button class="recycle-secondary" :disabled="busy" @click="loadCandidates(item)">查询可指派人员</button><button v-if="candidates[item.id] && candidates[item.id].page < candidates[item.id].totalPages" class="recycle-secondary" :disabled="busy" @click="loadCandidates(item, true)">加载更多候选人员</button><picker v-if="candidates[item.id]" :range="dispatchProfiles(item)" range-key="serviceName" :value="collectorSelections[item.id] || 0" @change="collectorSelections[item.id] = Number($event.detail.value)"><view class="recycle-select">{{ dispatchProfiles(item)[collectorSelections[item.id] || 0]?.serviceName || '暂无该区域合资格人员' }}</view></picker><button class="recycle-primary" :disabled="busy || !dispatchProfiles(item).length" @click="dispatch(item, 'assign')">{{ item.collectorId ? '转派给所选人员' : '指派给所选人员' }}</button><button v-if="item.status === 'confirmed'" class="recycle-secondary" :disabled="busy" @click="dispatch(item, 'release')">退回接单大厅</button></template>
            <button class="recycle-danger" :disabled="busy" @click="dispatch(item, 'cancel')">平台取消预约</button>
          </template>
        </view><view v-if="!overview.orders.length" class="recycle-empty">暂无预约订单</view>
      </template>
      <template v-if="tab === 'areas'">
        <view class="recycle-card"><text class="recycle-heading">服务覆盖与排班</text><text class="recycle-copy">服务范围由回收员在地图上圈选或设定圆形，经平台审核后生效，无需预先新增区域。</text><text class="recycle-muted">只有已审核人员开启接单并发布未来排班，用户所在地区才可预约；具体可用时段还会核验人员空闲情况和所选回收品类。</text><text class="recycle-muted recycle-copy">当前显示 {{ overview.areas.length }} 个申请服务地区、{{ (overview.availability || []).length }} 条未来排班记录{{ (overview.availability || []).length >= 1000 ? '（已达到本次查询上限）' : '' }}。</text></view>
        <view v-for="area in overview.areas" :key="area.id" class="recycle-card"><view class="recycle-row"><text class="recycle-heading">{{ area.name }}</text><text class="recycle-status">{{ areaSchedules(area.id).length ? '已发布排班' : '暂无排班' }}</text></view><text class="recycle-copy">{{ area.region?.join(' / ') || '历史服务范围，地区待核验' }} · {{ area.geometry?.type === 'circle' ? '圆形 ' + area.geometry.radiusMeters + '米' : area.geometry?.type === 'polygon' ? '多边形范围' : '旧地区范围' }}</text><button v-if="area.geometry" class="recycle-secondary" @click="rangePreviews['area:' + area.id] = !rangePreviews['area:' + area.id]">{{ rangePreviews['area:' + area.id] ? '收起地图' : '查看地图边界' }}</button><RecyclingServiceMap v-if="rangePreviews['area:' + area.id]" :areas="[area]" readonly /><view v-if="!area.region" class="recycle-copy"><text class="recycle-muted">旧版范围需要一次性核对省市区，核对后原人员与排班即可匹配预约地址。</text><ShopRegionPicker :model-value="legacyRegions[area.id] || ['', '', '']" :disabled="busy" @update:model-value="legacyRegions[area.id] = $event" /><button class="recycle-secondary" :disabled="busy" @click="mapLegacyArea(area)">核对旧范围所在地区</button></view><text v-if="area.description" class="recycle-muted">{{ area.description }}</text><text class="recycle-copy">未来排班 {{ areaSchedules(area.id).length }} 条 · {{ scheduledPeople(area.id) }} 名服务人员</text><view v-for="schedule in areaSchedules(area.id).slice(0, 5)" :key="schedule.id || `${schedule.userId}:${schedule.date}:${schedule.slot}`" class="recycle-event">{{ schedule.date }} {{ schedule.slot }} · 服务账号 {{ schedule.userId }}</view><text v-if="areaSchedules(area.id).length > 5" class="recycle-muted recycle-copy">另有 {{ areaSchedules(area.id).length - 5 }} 条未来排班，本卡仅摘要显示。</text></view>
        <view v-if="!overview.areas.length" class="recycle-empty">暂无回收员申请服务地区。回收员可直接选择省、市、区提交申请。</view>
      </template>
      <view v-if="tab !== 'areas'" class="recycle-row"><button class="recycle-secondary recycle-grow" :disabled="loading || page <= 1" @click="changePage(-1)">上一页</button><text>第 {{ page }} 页</text><button class="recycle-secondary recycle-grow" :disabled="loading || !hasNextPage" @click="changePage(1)">下一页</button></view>
    </template>
  </RecyclingShell>
</template>
<script>
import RecyclingShell from '@/pages-nonTheme/components/RecyclingShell.vue'
import RecyclingServiceMap from '@/pages-nonTheme/components/RecyclingServiceMap.vue'
import ShopRegionPicker from '@/pages-nonTheme/components/ShopRegionPicker.vue'
import { recyclingOverview, recyclingAdmin, recyclingRequest, bookingStatusText, collectorStatusText, mutationData } from '@/pages-nonTheme/api/recycling.js'
export default {
  components: { RecyclingShell, ShopRegionPicker, RecyclingServiceMap },
  data: () => ({ isDark: false, loading: false, busy: false, ready: false, error: '', page: 1, tab: 'applications', tabs: [{ key: 'applications', label: '申请审核' }, { key: 'collectors', label: '回收员' }, { key: 'orders', label: '预约调度' }, { key: 'areas', label: '服务覆盖' }], overview: { areas: [], profiles: [], applications: [], orders: [], availability: [] }, catalog: { types: [] }, reasons: {}, collectorSelections: {}, areaSelections: {}, candidates: {}, rangePreviews: {}, legacyRegions: {}, writes: {} }),
  computed: { hasNextPage() { return this.tab === 'orders' ? this.page * 100 < (this.overview.total || 0) : (this.tab === 'applications' ? this.overview.applications : this.overview.profiles).length >= 100 } },
  onShow() { this.isDark = uni.getStorageSync('app_theme') === 'dark'; this.load() },
  methods: {
    statusText: bookingStatusText, collectorStatusText,
    areaSchedules(areaId) { return (this.overview.availability || []).filter(row => Number(row.serviceAreaId) === Number(areaId)); },
    scheduledPeople(areaId) { return new Set(this.areaSchedules(areaId).map(row => row.userId)).size; },
    async mapLegacyArea(area) { const region = this.legacyRegions[area.id]; if (!Array.isArray(region) || region.length !== 3 || region.some(part => !String(part || '').trim())) { this.error = '请先核对旧服务范围对应的完整省市区'; return } if (await this.write(`areas/${area.id}`, { region, version: area.version }, 'PUT')) delete this.legacyRegions[area.id] },
    applicationAreas(item) { return this.overview.areas.filter(area => (item.areaIds || []).includes(area.id)) },
    names(values = [], rows = []) { return (values || []).map(id => rows.find(row => Number(row.id) === Number(id))?.name).filter(Boolean).join('、') },
    async load() { if (this.loading) return; this.loading = true; this.error = ''; try { const overview = await recyclingOverview({ page: this.page }); this.overview = overview; this.catalog = { types: overview.types || [], timeSlots: overview.timeSlots || [] }; this.candidates = {}; this.ready = true } catch (e) { this.error = e.message || '无权限或运营数据加载失败'; this.ready = false } finally { this.loading = false } },
    changeTab(tab) { if (this.loading || this.busy) return; this.tab = tab; if (this.page !== 1) { this.page = 1; this.load() } },
    changePage(direction) { if (this.loading || this.busy) return; this.page += direction; this.load(); uni.pageScrollTo({ scrollTop: 0 }) },
    async write(path, payload, method = 'POST') { if (this.busy) return; this.busy = true; try { await recyclingAdmin(path, payload, method); this.error = ''; await this.load(); uni.showToast({ title: '操作成功', icon: 'success' }); return true } catch (e) { this.error = e.message || '操作失败，请刷新'; return false } finally { this.busy = false } },
    review(item, decision) { const reason = String(this.reasons[`application:${item.id}`] || '').trim(); if (decision === 'rejected' && !reason) { this.error = '请填写驳回原因'; return } return this.write(`applications/${item.id}/review`, { decision, reason, version: item.version }) },
    profileStatus(item) { const reason = String(this.reasons[`profile:${item.id}`] || '').trim(); if (!reason) { this.error = '请填写停用或恢复原因'; return } return this.write(`collectors/${item.id}/status`, { status: item.status === 'approved' ? 'suspended' : 'approved', reason, version: item.version }) },
    dispatchProfiles(order) { return this.candidates[order.id]?.profiles || [] },
    async loadCandidates(order, more = false) { if (this.busy) return; this.busy = true; const previous = this.candidates[order.id]; const page = more ? (previous?.page || 0) + 1 : 1; try { const data = await recyclingRequest(`/api/admin/recycling/orders/${order.id}/candidates`, 'GET', { page }); this.candidates[order.id] = { ...data, profiles: more ? [...(previous?.profiles || []), ...(data.profiles || [])] : data.profiles || [] }; if (!more) this.collectorSelections[order.id] = 0; this.error = ''; } catch (e) { this.error = e.message || '候选人员加载失败'; } finally { this.busy = false; } },
    async dispatch(item, action) { const reason = String(this.reasons[`order:${item.id}`] || '').trim(); if (!reason) { this.error = '请填写调度说明'; return } const payload = { action, reason, version: item.version }; if (action === 'assign') payload.collectorUserId = this.dispatchProfiles(item)[this.collectorSelections[item.id] || 0]?.userId; if (action === 'map') payload.serviceAreaId = this.overview.areas[this.areaSelections[item.id] || 0]?.id; const key = `dispatch:${item.id}:${action}`; if (await this.write(`orders/${item.id}/dispatch`, mutationData(this.writes, key, payload))) delete this.writes[key] },
  }
}
</script>
